const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1000, height: 700 } });
page.on("console", (msg) => console.log("CONSOLE:", msg.type(), msg.text()));
page.on("pageerror", (err) => console.log("PAGEERROR:", err.message));

// The dev proxy forwards /api/* verbatim to the API, which serves its routes
// unprefixed — a pre-existing mismatch, out of scope here. Route around it
// just for this local visual check.
await page.route("**/api/**", async (route) => {
  const url = new URL(route.request().url());
  const target = "http://localhost:8787" + url.pathname.replace(/^\/api/, "") + url.search;
  const response = await fetch(target, {
    method: route.request().method(),
    headers: route.request().headers(),
    body: route.request().postData() ?? undefined,
  });
  const body = await response.text();
  await route.fulfill({ status: response.status, body, contentType: "application/json" });
});

await page.goto("http://localhost:5173/sites/acme/posts");
await page.waitForSelector('[aria-label="Post stats"]', { timeout: 10000 });
await page.screenshot({ path: "/tmp/postlist.png" });
await browser.close();

